-- Helper to check if an element is in an array
def ArrayContains (as : Array Nat) (k : Nat) : Prop :=
  ∃ i, i < as.size ∧ as[i]! = k

-- Helper to count occurrences of an element in an array
def CountOccurrences (as : Array Nat) (k : Nat) : Nat :=
  as.foldl (fun count x => if x = k then count + 1 else count) 0

-- Helper to check if k is present in the array (with respect to lt equivalence)
def IsPresent (lt : Int → Int → Bool) (k : Int) (as : Array Int) : Prop :=
  ∃ i, i < as.size ∧ lt k as[i]! = false ∧ lt as[i]! k = false

-- Helper to get the index of k in the array (if present)
def GetIndex (lt : Int → Int → Bool) (k : Int) (as : Array Int) : Option Nat :=
  as.findIdx? (fun x => lt k x = false ∧ lt x k = false)

-- Helper to check if result array is sorted
def ResultIsSorted (lt : Int → Int → Bool) (result : Array Int) : Prop :=
  IsSorted lt result

-- Helper to check that result has correct size
def ResultHasCorrectSize (as result : Array Int) (wasPresent : Bool) : Prop :=
  if wasPresent then result.size = as.size else result.size = as.size + 1

-- Helper to check that k is present in result
def ResultContainsK (lt : Int → Int → Bool) (k : Int) (result : Array Int) : Prop :=
  IsPresent lt k result

-- Auxiliary definition to express equivalence under the ordering
def equiv_under_lt (lt : Nat → Nat → Bool) (x y : Nat) : Prop :=
  ¬(lt x y) ∧ ¬(lt y x)

-- Auxiliary definition to express that an array is sorted with respect to lt
def is_sorted (as : Array Nat) (lt : Nat → Nat → Bool) : Prop :=
  ∀ i j : Nat, i < as.size → j < as.size → i ≤ j → ¬(lt (as[i]!) (as[j]!)) = false

-- Auxiliary definition for element equivalence under the ordering lt
def IsEquivalent (lt : Nat → Nat → Bool) (a b : Nat) : Prop :=
  lt a b = false ∧ lt b a = false

-- Auxiliary definition for checking if k is equivalent to some element in the range
def ContainsEquivalent (as : Array Nat) (k : Nat) (lt : Nat → Nat → Bool) (lo hi : Nat) : Prop :=
  ∃ i, lo ≤ i ∧ i ≤ hi ∧ i < as.size ∧ IsEquivalent lt k as[i]!

def find_first_index (arr : Array Nat) (a : Nat) : Option Nat :=
  let rec loop (i : Nat) : Option Nat :=
    if h : i < arr.size then
      if arr[i] = a then some i else loop (i + 1)
    else none
  loop 0

def remove_at_index (arr : Array Nat) (idx : Nat) : Array Nat :=
  if h : idx < arr.size then
    arr.popn (idx + 1) |>.append (arr.extract (idx + 1) arr.size)
  else
    arr

def expected_result (as : Array Nat) (a : Nat) : Array Nat :=
  match find_first_index as a with
  | some idx => remove_at_index as idx
  | none => as

-- Helper function to check if an element appears in the result array
def elem_in_array (x : Nat) (arr : Array Nat) (beq : BEq Nat) : Prop :=
  ∃ i : Fin arr.size, arr[i] == x

-- Helper function to get the first occurrence index of an element in an array
def first_occurrence (x : Nat) (arr : Array Nat) (beq : BEq Nat) : Option (Fin arr.size) :=
  arr.findIdx? (fun y => y == x)

-- Helper to check if index i starts a new run (i.e., arr[i] != arr[i-1])
def starts_run (arr : Array Nat) (i : Nat) (beq : BEq Nat) : Prop :=
  i < arr.size ∧ (i = 0 ∨ (i > 0 ∧ ¬(arr[i]! == arr[i-1]!)))

def find_predicate_holds (p : Nat → Bool) (as : Array Nat) (x : Nat) : Prop :=
  ∃ (i : Fin as.size), as[i] = x ∧ p x

def find_first_index (p : Nat → Bool) (as : Array Nat) : Option Nat :=
  match as.findIdx? (λ x => p x) with
  | some i => some (as[i]!)
  | none => none

-- Helper function to compute the expected result of flatMap
def flatMapResult {α β : Type _} (f : α → Array β) (as : Array α) : Array β :=
  as.foldl (fun acc a => acc ++ f a) #[]

-- Helper lemma: size of flatMap result
def flatMapSize {α β : Type _} (f : α → Array β) (as : Array α) : Nat :=
  as.foldl (fun acc a => acc + (f a).size) 0

-- Helper function to check if as is a prefix of bs
def isPrefixSpec (as bs : Array Nat) : Prop :=
  as.size ≤ bs.size ∧ ∀ i : Nat, i < as.size → as[i]! = bs[i]!

-- Helper to check if two arrays are pairwise equivalent up to index i
def arrays_equiv_upto (as bs : Array Nat) (i : Nat) : Prop :=
  ∀ j, j < i → as[j]! == bs[j]!

-- Helper to check if as is a prefix of bs (pairwise equivalent and shorter)
def is_prefix_equiv (as bs : Array Nat) : Prop :=
  as.size < bs.size ∧ arrays_equiv_upto as bs as.size

-- Helper to check if there exists an index where lt holds and all previous elements are equivalent
def exists_lex_index (as bs : Array Nat) (lt : Nat → Nat → Bool) : Prop :=
  ∃ i, i < as.size ∧ i < bs.size ∧ lt as[i]! bs[i]! ∧ arrays_equiv_upto as bs i

