-- Check if an array is sorted according to a comparison function
def isSorted (arr : Array Nat) (lt : Nat → Nat → Bool) (start : Nat) (stop : Nat) : Prop :=
  ∀ i j, start ≤ i → i < j → j < stop → lt arr[i]! arr[j]! = true ∨ arr[i]! = arr[j]!

-- Check if two arrays are permutations of each other in a given range
def isPermutation (as bs : Array Nat) (lo hi : Nat) : Prop :=
  ∀ x, (as.toList.take hi |>.drop lo).count x = (bs.toList.take hi |>.drop lo).count x

-- The array elements outside the sorted range remain unchanged
def unchangedOutside (as result : Array Nat) (lo hi : Nat) : Prop :=
  (∀ i, i < lo → result[i]? = as[i]?) ∧ (∀ i, hi < i → result[i]? = as[i]?)

