-- Helper function to check if k divides all non-constant coefficients
def divides_all_coeffs (k : Int) (p : Int.Linear.Poly) : Prop :=
  ∀ v : Int, v ∈ p.vars.toList → (p.coeff v) % k = 0

-- Auxiliary definitions for postcondition
def hasMonomialWithCoeff (p : Int.Linear.Poly) (x : Nat) (k : Nat) (c : Int) : Prop :=
  ∃ (coeff : Int), p.coeff x = coeff ∧ coeff = (k : Int) ∧ c = coeff

def isEliminatedUsing (p : Int.Linear.Poly) (x : Nat) (c : Int) : Prop :=
  ∃ (k : Nat), hasMonomialWithCoeff p x k c ∧ c ≠ 0

-- Helper to check if a coefficient exists in the polynomial
def hasCoeff (poly : Int.Linear.Poly) (v : Int.Linear.Var) (c : Int) : Prop :=
  ∃ (t : Int.Linear.Term), t ∈ poly.terms ∧ t.var = v ∧ t.coeff = c

-- Helper to get all coefficients from the polynomial
def getAllCoeffs (poly : Int.Linear.Poly) : List Int :=
  poly.terms.map (·.coeff)

-- Helper to check if a coefficient has the minimum absolute value among all coefficients
def hasMinAbsCoeff (poly : Int.Linear.Poly) (c : Int) : Prop :=
  c ≠ 0 ∧ ∀ (t : Int.Linear.Term), t ∈ poly.terms → t.coeff ≠ 0 → Int.natAbs c ≤ Int.natAbs t.coeff

-- Helper function to check if a natural number is divisible by an integer's absolute value
def isDivisibleByAbs (n : Nat) (a : Int) : Prop :=
  a = 0 ∨ (n % a.natAbs = 0)

-- Helper function to check if n is a common multiple of a and b
def isCommonMultiple (n : Nat) (a b : Int) : Prop :=
  isDivisibleByAbs n a ∧ isDivisibleByAbs n b

