def isWhitespace (c : Char) : Bool :=
  c = ' ' ∨ c = '\t' ∨ c = '\n' ∨ c = '\r' || c = '\x0c' || c = '\x0b'

def removeTrailingWhitespace (s : String) : String :=
  let chars := s.toList
  let nonWhitespacePos := chars.findIdx? (λ c => ¬isWhitespace c) (start := chars.length) (back := true)
  match nonWhitespacePos with
  | none => ""
  | some pos => (chars.take (pos + 1)).asString

